const pair = (en, es, I) => I.T(en, es);
const safe = (s) => String(s ?? "").replace(/[<>]/g, "").slice(0, 500);
const dl = (name, data, type = "application/json") => { const url = URL.createObjectURL(new Blob([data], { type })), a = document.createElement("a"); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 0); };
const now = () => new Date().toISOString();
const makeId = (prefix) => `${prefix}-${crypto.randomUUID()}`;
const label = (s, I) => I.spanish ? s.es : s.en;
const parseCsvLine = (line) => { const out = []; let value = "", quoted = false; for (let i = 0; i < line.length; i++) { const c = line[i]; if (c === '"' && line[i + 1] === '"' && quoted) { value += '"'; i++; } else if (c === '"') quoted = !quoted; else if (c === "," && !quoted) { out.push(value); value = ""; } else value += c; } out.push(value); return out; };
const STORAGE_EXPORT_VERSION = "lp-el-program-export/1";

async function archive() {
  const records = [];
  for (const kind of ["profile", "form", "benchmark", "module", "outbox", "accepted-strategy", "objective", "rubric", "question", "live-room"]) records.push(...await db.listRecords(kind));
  records.sort((a, b) => a.id.localeCompare(b.id));
  const payload = { schema: STORAGE_EXPORT_VERSION, exportedAt: now(), records };
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(JSON.stringify(payload)));
  return { ...payload, checksum: [...new Uint8Array(digest)].map((x) => x.toString(16).padStart(2, "0")).join("") };
}
async function validateArchive(value) {
  if (value?.schema !== STORAGE_EXPORT_VERSION || !Array.isArray(value.records) || value.records.some((r) => !r?.id || !r?.kind)) throw new Error("This is not a valid local program archive.");
  const payload = { schema: value.schema, exportedAt: value.exportedAt, records: value.records };
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(JSON.stringify(payload)));
  const actual = [...new Uint8Array(digest)].map((x) => x.toString(16).padStart(2, "0")).join("");
  if (actual !== value.checksum) throw new Error("The archive checksum did not match; nothing was imported.");
  return value.records;
}

