async function livePage(I) {
  const rooms = await db.listRecords("live-room"), packs = await listTaskPacks().catch(() => []);
  return html`<h2>${pair("Live speaking rooms · mock preview", "Salas de conversación · vista simulada", I)}</h2><p>${pair("Offline mock only. No participants connect, no microphone is opened and no recording is made. STOP: no realtime app, storage bucket, secret or migration is configured.", "Solo simulación local. No se conectan participantes, no se abre el micrófono ni se graba. STOP: no hay aplicación en vivo, almacenamiento, secreto ni migración configurados.", I)}</p><form class="panel" data-live-create><label class="field">${pair("Class label (local only)", "Nombre de clase (solo local)", I)}<input name="className" required maxlength="60"></label><label class="field">${pair("Mock roster size", "Tamaño simulado del grupo de clase", I)}<input name="participants" type="number" min="2" max="36" value="12"></label><label class="field">${pair("Task pack", "Paquete de tarea", I)}<select name="taskPack"><option value="">${pair("Choose a local draft", "Elige un borrador local", I)}</option>${packs.map((p) => html`<option value="${p.id}">${safe(p.title.en)}</option>`)}</select></label><label class="field">${pair("Group size", "Tamaño del grupo", I)}<select name="groupSize">${[2, 3, 4, 5, 6].map((n) => html`<option value="${n}">${n}</option>`)}</select></label><label class="field">${pair("Recording length (practice setting)", "Duración de grabación (opción de práctica)", I)}<select name="minutes">${[5, 10, 15, 30, 45, 60].map((n) => html`<option value="${n}">${n} min</option>`)}</select></label><label class="field">${pair("Waiting-room directions", "Instrucciones de sala de espera", I)}<textarea name="description" maxlength="200"></textarea></label><label><input type="checkbox" name="video">${pair("Allow video (mock only; audio is default)", "Permitir video (solo simulación; audio es la opción inicial)", I)}</label><button class="btn btn-primary" type="button" data-live-create-room>${pair("Create mock rooms", "Crear salas simuladas", I)}</button></form>${rooms.map((r) => html`<section class="panel" data-live-room="${r.id}"><h3>${safe(r.className)} · ${r.rooms.length} ${pair("rooms", "salas", I)} · ${safe(r.minutes)} min</h3><p>${safe(r.description || "")}</p><p class="fine">${pair("Consent shown before join", "Se muestra consentimiento antes de entrar", I)}: “${I.spanish ? "Esta sala se graba; tu docente puede escuchar." : "This room is recorded; your teacher can listen."}”</p><div class="row-actions"><button class="btn small" data-live-reshuffle="${r.id}">${pair("Shuffle rooms", "Mezclar salas", I)}</button><button class="btn small" data-live-add-room="${r.id}">${pair("Add room", "Agregar sala", I)}</button></div><div class="lp-extended-grid">${r.rooms.map((room, ri) => html`<article class="panel" data-room-index="${ri}"><h4>${safe(room.id)} · ${roomStatus(room)}</h4><ul>${room.participants.map((p) => html`<li>${safe(p.alias)} · ${p.absent ? pair("Absent", "Ausente", I) : p.online ? pair("Online", "En línea", I) : pair("Offline", "Sin conexión", I)} ${!p.joined ? html`<button type="button" class="btn small" data-live-join="${r.id}:${ri}:${p.id}">${pair("Join visible", "Unirse visible", I)}</button><button type="button" class="btn small ghost" data-live-join-hidden="${r.id}:${ri}:${p.id}">${pair("Join as observer", "Unirse como observador", I)}</button>` : pair("Joined", "Conectado", I)} <button type="button" class="btn small ghost" data-live-absent="${r.id}:${ri}:${p.id}">${pair("Toggle absent", "Cambiar ausencia", I)}</button></li>`)}</ul><div class="row-actions"><button class="btn small" data-live-action="${r.id}:${ri}:start">${pair("Open room", "Abrir sala", I)}</button><button class="btn small" data-live-action="${r.id}:${ri}:stop">${pair("Stop mock recording", "Detener grabación simulada", I)}</button><button class="btn small" data-live-action="${r.id}:${ri}:recorded">${pair("Mark processing complete", "Marcar proceso completo", I)}</button><button class="btn small ghost" data-live-action="${r.id}:${ri}:reset">${pair("Reset room", "Reiniciar sala", I)}</button></div><p>${room.recording ? pair("Mock recording metadata only · 30-day retention contract · no media file exists", "Solo metadatos de grabación simulada · contrato de retención de 30 días · no existe un archivo multimedia", I) : ""}</p></article>`)}</div><p class="fine">${pair("Provider: mock · Cloudflare adapter disabled pending explicit provisioning approval.", "Proveedor: simulado · adaptador Cloudflare desactivado hasta autorización explícita de configuración.", I)}</p></section>`)}`;
}

const pages = { profiles: profilePage, forms: formsPage, strategies: strategyPage, instruction: instructionPage, objectives: objectivePage, benchmark: benchmarkPage, learning: learningPage, import: importPage, letters: lettersPage, live: livePage, rubrics: rubricPage, banks: bankPage, reports: reportsPage };

export async function render(ctx) {
  const I = i18nFor(ctx), id = ctx.route.id || "", active = pages[id];
  if (!ACCESS_LAB_FLAGS.elProgramEnabled) return { title: pair("Teacher Program Studio", "Estudio de programa docente", I), html: html`<section class="panel"><h1>${pair("This workspace is not available.", "Este espacio no está disponible.", I)}</h1></section>` };
  if (id === "live" && !ACCESS_LAB_FLAGS.liveRoomsMockEnabled) return { title: pair("Live room preview", "Vista de salas en vivo", I), html: html`<section class="panel"><h1>${pair("This preview is not available.", "Esta vista no está disponible.", I)}</h1></section>` };
  return { title: pair("Teacher Program Studio", "Estudio de programa docente", I), html: html`<article class="pg-root"><p class="eyebrow">${pair("Teacher Hub · local workspace", "Centro docente · espacio local", I)}</p><h1 tabindex="-1">${pair("Teacher Program Studio", "Estudio de programa docente", I)}</h1><p class="lead">${pair("Program tools for teacher-entered records, instruction and planning.", "Herramientas de programa para registros escritos por docentes, enseñanza y planificación.", I)}</p>${navHTML(ctx.route, I)}${active ? await active(I) : html`<section class="panel"><h2>${pair("A local-first teacher workspace", "Un espacio docente local", I)}</h2><p>${pair("Create and manage neutral forms, review strategies, compose language objectives, compare teacher-reported benchmarks and complete short learning modules.", "Crea y administra formularios neutrales, revisa estrategias, redacta objetivos de lenguaje, compara evaluaciones informadas por docentes y completa módulos breves.", I)}</p><ul>${NAV.slice(1).map(([, en, es]) => html`<li>${pair(en, es, I)}</li>`)}</ul><a class="btn btn-primary" href="${BASE}/program/profiles">${pair("Open teacher workspace", "Abrir espacio docente", I)}</a></section>`}</article>` };
}

export function mount(root) {
  const select = root.querySelector("[data-form-template]");
  if (select) select.dispatchEvent(new Event("change", { bubbles: true }));
}

